// Product images per registry entry (ADR 10), generated by scripts/import-images.ts.
// An image is decoration: it never stands for support or for a confirmed model.
import data from '../../registry/images.json';

export type DeviceImage = {
  src: string;
  /** 'model': this product. 'line': the same shell or product line, not this exact variant. */
  match: 'model' | 'line';
  width: number;
  height: number;
};

const devices = data.devices as Record<string, { file: string; match: 'model' | 'line' }>;
const images = data.images as Record<string, { width: number; height: number }>;

export function imageFor(entryId: string | undefined): DeviceImage | null {
  const d = entryId ? devices[entryId] : undefined;
  const meta = d && images[d.file];
  if (!d || !meta) return null;
  return { src: `${import.meta.env.BASE_URL}devices/${d.file}`, match: d.match, width: meta.width, height: meta.height };
}
